    if v_lesson is null then
      insert into public.cf_lessons (school_id, owner_id, title, subject, plan, slides, terms)
      select c.school_id, c.owner_id, v_spec.title, v_spec.subject, v_spec.plan, v_spec.slides, v_spec.terms from public.cf_curr_courses c where c.id = v_course
      returning id into v_lesson;
    else
      update public.cf_lessons set title = v_spec.title, subject = v_spec.subject, plan = v_spec.plan, slides = v_spec.slides, terms = v_spec.terms, updated_at = now() where id = v_lesson;
    end if;
    insert into public.cf_curr_lessons (lesson_id, module_id, position) values (v_lesson, v_module, v_spec.position)
    on conflict (lesson_id) do update set module_id = excluded.module_id, position = excluded.position;
    v_lesson := null;
  end loop;

  -- 2.6: the canvas lesson d1e472f0 keeps its slides; it moves to position 5 and gets the practice and the mini-test (kept before the last two slides)
  select l.id, l.slides into v_lesson, v_old from public.cf_lessons l where l.title like '%2.6%' and l.id in (select cl.lesson_id from public.cf_curr_lessons cl join public.cf_curr_modules m on m.id = cl.module_id where m.course_id = v_course) limit 1;
  if v_lesson is not null then
    insert into public.cf_curr_lessons (lesson_id, module_id, position) values (v_lesson, v_module, 5)
    on conflict (lesson_id) do update set module_id = excluded.module_id, position = excluded.position;
    if not exists (select 1 from jsonb_array_elements(v_old) s where s ? 'levels') then
      v_new := $sl$[{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика: ASCII кодын оқы","prompt":"Жұппен орында. ASCII кестесін қолдан. L1 орындалмайынша L2 ашылмайды.","points":6,"levels":[{"lv":1,"points":1,"title":"Байт → ондық","variants":[{"v":"A","prompt":"01001001 байтын ондық санға аудар.","accept":["73"],"explanation":"64+8+1 = 73"},{"v":"B","prompt":"01101011 байтын ондық санға аудар.","accept":["107"],"explanation":"64+32+8+2+1 = 107"}]},{"lv":2,"points":2,"title":"Байт → таңба","variants":[{"v":"A","prompt":"01001001 байты ASCII-де қандай таңба? (бір әріп)","accept":["i"],"explanation":"73 = I"},{"v":"B","prompt":"01101110 байты ASCII-де қандай таңба? (бір әріп)","accept":["n"],"explanation":"110 = n"}]},{"lv":3,"points":3,"title":"Хабарды оқы","variants":[{"v":"A","prompt":"01001001 00100000 01101011 01101110 01101111 01110111 — осы 6 байт қандай мәтін? (әріптер мен бос орын)","accept":["i know"],"explanation":"I, бос орын, k, n, o, w"},{"v":"B","prompt":"01000001 01010011 01000011 01001001 01001001 — осы 5 байт қандай сөз?","accept":["ascii"],"explanation":"A, S, C, I, I"}]}]},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Өзіңді тексер · 1","prompt":"7 битпен неше түрлі таңбаны кодтауға болады?","options":["7","64","128","256"],"answer":2,"explanation":"2⁷ = 128.","points":1},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Өзіңді тексер · 2","prompt":"01000001 кодына қандай ASCII таңбасы сәйкес?","options":["A","a","B","бос орын"],"answer":0,"explanation":"01000001 = 65 = A.","points":1},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Өзіңді тексер · 3","prompt":"Unicode-тың ASCII-ден басты артықшылығы қандай?","options":["тек сандарды кодтайды","көп тілдің таңбаларын қамтиды","әрқашан 2 бит алады","жұмыс істемейді"],"answer":1,"explanation":"Unicode әлемнің көптеген тілдерінің таңбаларын қамтиды.","points":1}]$sl$::jsonb;
      select min(i - 1) into v_idx from jsonb_array_elements(v_old) with ordinality a(s, i) where s->>'title' like 'Өзіңді тексер%' and s->>'type' is distinct from 'quiz';
      v_idx := coalesce(v_idx, jsonb_array_length(v_old) - 2);
      update public.cf_lessons set slides = (
        select coalesce(jsonb_agg(s order by o), '[]'::jsonb) from (
          select s, i::numeric as o from jsonb_array_elements(v_old) with ordinality a(s, i) where i - 1 < v_idx
          union all select s, v_idx + (i::numeric / 100) from jsonb_array_elements(v_new) with ordinality b(s, i)
          union all select s, i::numeric + 100 from jsonb_array_elements(v_old) with ordinality c(s, i) where i - 1 >= v_idx
        ) z), updated_at = now() where id = v_lesson;
    end if;
  end if;
end;
$ch2$;
